19	// cacheVersion is bumped when matching logic changes to force cache invalidation.
20	// v2: added ResolveSkillName fuzzy matching for LLM-extracted signal names.
21	// v3: attribute Skill tool sessions by reading committed transcripts when skill_signals are absent.
22	const cacheVersion = "v3"
23	
24	// resolveSkillName matches an LLM-extracted skill signal name to a discovered skill.
25	// LLM-extracted names often differ from canonical names (e.g. "e2e:triage" for skill "e2e",
26	// "superpowers:writing-plans" for "writing-plans", "cli-e2e-failure-fix" for "e2e").
27	//
28	// Match priority:
29	//  1. Exact match
30	//  2. Signal is a sub-skill: "parent:child" where parent matches a discovered skill
31	//  3. Last segment match: "prefix:name" where name matches a discovered skill
32	//  4. Discovered skill name is contained in the signal name as a word boundary
33	func ResolveSkillName(signalName string, skillMap map[string]SkillRow) (SkillRow, bool) {
34		// 1. Exact match.
35		if skill, ok := skillMap[signalName]; ok {
36			return skill, true
37		}
38	
39		// 2. Sub-skill: signal "e2e:triage" matches discovered "e2e".
40		if idx := strings.IndexByte(signalName, ':'); idx > 0 {
41			parent := signalName[:idx]
42			if skill, ok := skillMap[parent]; ok {
43				return skill, true
44			}
45		}
46	
47		// 3. Last segment: signal "superpowers:writing-plans" matches discovered "writing-plans".
48		if idx := strings.LastIndexByte(signalName, ':'); idx >= 0 && idx < len(signalName)-1 {
49			lastSeg := signalName[idx+1:]
50			if skill, ok := skillMap[lastSeg]; ok {
51				return skill, true
52			}
53		}
54	
55		// 4. Discovered skill name appears as a delimited segment in the signal.
56		// E.g. signal "cli-e2e-failure-fix" contains discovered skill "e2e".
57		// We check word boundaries using "-" and ":" as delimiters.
58		for name, skill := range skillMap {
59			if len(name) < 2 {
60				continue // skip very short names to avoid false positives
61			}
62			// Check if name appears bounded by delimiters or string edges.
63			searchIn := signalName
64			for {
65				idx := strings.Index(searchIn, name)
66				if idx < 0 {
67					break
68				}
69				leftOK := idx == 0 || searchIn[idx-1] == '-' || searchIn[idx-1] == ':'
70				rightEnd := idx + len(name)
71				rightOK := rightEnd == len(searchIn) || searchIn[rightEnd] == '-' || searchIn[rightEnd] == ':'
72				if leftOK && rightOK {
73					return skill, true
74				}
75				searchIn = searchIn[idx+1:]
76			}
77		}
78	
79		return SkillRow{}, false
80	}
