82	// PopulateFromInsightsDB populates the skill analytics DB from insightsdb data.
83	// It queries skill_signals and tool_calls to find sessions that used discovered skills.
84	func (sdb *SkillDB) PopulateFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) error {
85		if len(discoveredSkills) == 0 {
86			return nil
87		}
88	
89		// Collect skill names for querying.
90		skillNames := make([]string, len(discoveredSkills))
91		skillMap := make(map[string]SkillRow, len(discoveredSkills))
92		for i, s := range discoveredSkills {
93			skillNames[i] = s.Name
94			skillMap[s.Name] = s
95		}
96	
97		tx, err := sdb.BeginTx(ctx)
98		if err != nil {
99			return fmt.Errorf("begin transaction: %w", err)
100		}
101		defer func() {
102			if err != nil {
103				_ = tx.Rollback() //nolint:errcheck // Rollback after failed tx; error is irrelevant
104			}
105		}()
106	
107		// Track which sessions we've already inserted to avoid duplicates.
108		type sessionKey struct {
109			skillName    string
110			checkpointID string
111			sessionIndex int
112		}
113		inserted := make(map[sessionKey]bool)
114	
115		// Step 1: From skill_signals — sessions with friction for specific skills.
116		// Fetch all signals and resolve names in Go, since LLM-extracted names
117		// often differ from canonical discovered names.
118		signals, err := idb.QueryAllSkillSignals(ctx)
119		if err != nil {
120			return fmt.Errorf("query skill signals: %w", err)
121		}
122	
123		for _, sig := range signals {
124			skill, ok := ResolveSkillName(sig.SkillName, skillMap)
125			if !ok {
126				logging.Debug(ctx, "skill signal name not matched to any discovered skill",
127					"signal_name", sig.SkillName)
128				continue
129			}
130	
131			key := sessionKey{skill.Name, sig.CheckpointID, sig.SessionIndex}
132			if inserted[key] {
133				continue
134			}
135			inserted[key] = true
136	
137			frictionCount := len(sig.Friction)
138			outcome := "success"
139			if frictionCount > 0 {
140				outcome = "friction"
141			}
142	
143			if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
144				SkillName:     skill.Name,
145				SourceAgent:   skill.SourceAgent,
146				CheckpointID:  sig.CheckpointID,
147				SessionIndex:  sig.SessionIndex,
148				SessionID:     sig.SessionID,
149				Agent:         sig.Agent,
150				Model:         sig.Model,
151				Branch:        sig.Branch,
152				CreatedAt:     sig.CreatedAt,
153				TotalTokens:   sig.TotalTokens,
154				TurnCount:     sig.TurnCount,
155				OverallScore:  sig.OverallScore,
156				FrictionCount: frictionCount,
157				Outcome:       outcome,
158			}); err != nil {
159				return fmt.Errorf("insert skill session: %w", err)
160			}
161	
162			// Insert friction items.
163			for _, f := range sig.Friction {
164				if err = sdb.InsertFrictionTx(ctx, tx,
165					skill.Name, skill.SourceAgent,
166					sig.CheckpointID, sig.SessionIndex,
167					f, "",
168				); err != nil {
169					return fmt.Errorf("insert skill friction: %w", err)
170				}
171			}
172	
173			// Insert missing instruction if present.
174			if sig.MissingInstruction != "" {
175				evidence := strings.Join(sig.Friction, "\n")
176				if err = sdb.InsertMissingInstructionTx(ctx, tx,
177					skill.Name, skill.SourceAgent,
178					sig.CheckpointID, sig.SessionIndex,
179					sig.MissingInstruction, evidence,
180				); err != nil {
181					return fmt.Errorf("insert missing instruction: %w", err)
182				}
183			}
184		}
185	
186		// Step 2: From tool_calls — sessions that used the Skill tool (friction-free uses).
187		toolSessions, err := idb.QuerySkillToolCallSessions(ctx)
188		if err != nil {
189			return fmt.Errorf("query skill tool call sessions: %w", err)
190		}
191	
192		var store *checkpoint.GitStore
193		getStore := func() (*checkpoint.GitStore, error) {
194			if store != nil {
195				return store, nil
196			}
197			repo, openErr := git.PlainOpenWithOptions(repoRoot, &git.PlainOpenOptions{DetectDotGit: true})
198			if openErr != nil {
199				return nil, fmt.Errorf("open repository for transcript fallback: %w", openErr)
200			}
201			store = checkpoint.NewGitStore(repo)
202			return store, nil
203		}
204	
205		for _, ts := range toolSessions {
206			var matchedTranscriptSkill bool
207	
208			cpID, cpErr := id.NewCheckpointID(ts.CheckpointID)
209			if cpErr == nil {
210				store, storeErr := getStore()
211				if storeErr != nil {
212					return storeErr
213				}
214	
215				content, readErr := store.ReadSessionContent(ctx, cpID, ts.SessionIndex)
216				if readErr == nil && content != nil && len(content.Transcript) > 0 {
217					invokedSkills, extractErr := extractSkillInvocationsFromTranscript(content.Transcript)
218					if extractErr != nil {
219						return fmt.Errorf("extract skill invocations from transcript for %s/%d: %w",
220							ts.CheckpointID, ts.SessionIndex, extractErr)
221					}
222	
223					for _, invokedSkill := range invokedSkills {
224						skill, ok := ResolveSkillName(invokedSkill, skillMap)
225						if !ok {
226							continue
227						}
228	
229						key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
230						if inserted[key] {
231							continue
232						}
233						inserted[key] = true
234						matchedTranscriptSkill = true
235	
236						if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
237							SkillName:    skill.Name,
238							SourceAgent:  skill.SourceAgent,
239							CheckpointID: ts.CheckpointID,
240							SessionIndex: ts.SessionIndex,
241							SessionID:    ts.SessionID,
242							Agent:        ts.Agent,
243							Model:        ts.Model,
244							Branch:       ts.Branch,
245							CreatedAt:    ts.CreatedAt,
246							TotalTokens:  ts.TotalTokens,
247							TurnCount:    ts.TurnCount,
248							OverallScore: ts.OverallScore,
249							Outcome:      "success",
250						}); err != nil {
251							return fmt.Errorf("insert transcript-attributed skill session: %w", err)
252						}
253					}
254				}
255			}
256	
257			if matchedTranscriptSkill {
258				continue
259			}
260	
261			// We can't determine which specific skill was used from tool_calls alone,
262			// so we skip sessions already covered by skill_signals.
263			// These sessions indicate the Skill tool was invoked but we only record
264			// them if there's exactly one discovered skill (unambiguous attribution).
265			if len(discoveredSkills) == 1 {
266				skill := discoveredSkills[0]
267				key := sessionKey{skill.Name, ts.CheckpointID, ts.SessionIndex}
268				if inserted[key] {
269					continue
270				}
271				inserted[key] = true
272	
273				if err = sdb.InsertSessionTx(ctx, tx, SkillSessionRow{
274					SkillName:    skill.Name,
275					SourceAgent:  skill.SourceAgent,
276					CheckpointID: ts.CheckpointID,
277					SessionIndex: ts.SessionIndex,
278					SessionID:    ts.SessionID,
279					Agent:        ts.Agent,
280					Model:        ts.Model,
281					Branch:       ts.Branch,
282					CreatedAt:    ts.CreatedAt,
283					TotalTokens:  ts.TotalTokens,
284					TurnCount:    ts.TurnCount,
285					OverallScore: ts.OverallScore,
286					Outcome:      "success",
287				}); err != nil {
288					return fmt.Errorf("insert tool call session: %w", err)
289				}
290			}
291		}
292	
293		if err = tx.Commit(); err != nil {
294			return fmt.Errorf("commit transaction: %w", err)
295		}
296		return nil
297	}
