299	// RefreshFromInsightsDB checks if the cache is stale and repopulates if needed.
300	// Returns true if the cache was refreshed.
301	func (sdb *SkillDB) RefreshFromInsightsDB(ctx context.Context, idb *insightsdb.InsightsDB, discoveredSkills []SkillRow, repoRoot string) (bool, error) {
302		// Check insightsdb branch tip with cache version prefix.
303		// Bumping cacheVersion forces re-population even if the branch tip hasn't changed,
304		// e.g. after fixing the skill name matching logic.
305		currentTip, err := idb.GetBranchTip(ctx)
306		if err != nil {
307			return false, fmt.Errorf("get insightsdb branch tip: %w", err)
308		}
309	
310		versionedTip := cacheVersion + ":" + currentTip
311	
312		cachedTip, err := sdb.GetCacheTip(ctx)
313		if err != nil {
314			return false, fmt.Errorf("get skilldb cache tip: %w", err)
315		}
316	
317		if versionedTip != "" && versionedTip == cachedTip {
318			return false, nil
319		}
320	
321		// Upsert discovered skills.
322		now := time.Now().UTC()
323		for _, skill := range discoveredSkills {
324			if err = sdb.UpsertSkill(ctx, SkillRow{
325				Name:         skill.Name,
326				SourceAgent:  skill.SourceAgent,
327				Path:         skill.Path,
328				Kind:         skill.Kind,
329				DiscoveredAt: now,
330				LastSeenAt:   now,
331			}); err != nil {
332				return false, fmt.Errorf("upsert skill %q: %w", skill.Name, err)
333			}
334		}
335	
336		// Clear existing session data before repopulating.
337		if err = sdb.clearSessionData(ctx); err != nil {
338			return false, fmt.Errorf("clear session data: %w", err)
339		}
340	
341		// Populate from insightsdb.
342		if err = sdb.PopulateFromInsightsDB(ctx, idb, discoveredSkills, repoRoot); err != nil {
343			return false, fmt.Errorf("populate from insightsdb: %w", err)
344		}
345	
346		// Update cache tip with version prefix.
347		if versionedTip != "" {
348			if err = sdb.SetCacheTip(ctx, versionedTip); err != nil {
349				return false, fmt.Errorf("set cache tip: %w", err)
350			}
351		}
352	
353		return true, nil
354	}
