356	// clearSessionData removes all rows from session-related tables.
357	func (sdb *SkillDB) clearSessionData(ctx context.Context) error {
358		tables := []string{"skill_sessions", "skill_friction", "skill_missing_instructions"}
359		for _, table := range tables {
360			if _, err := sdb.db.ExecContext(ctx, "DELETE FROM "+table); err != nil { //nolint:gosec // table names are hardcoded
361				return fmt.Errorf("clear %s: %w", table, err)
362			}
363		}
364		return nil
365	}
366	
367	func extractSkillInvocationsFromTranscript(content []byte) ([]string, error) {
368		lines, err := transcript.ParseFromBytes(content)
369		if err != nil {
370			return nil, fmt.Errorf("parse transcript: %w", err)
371		}
372	
373		seen := make(map[string]bool)
374		var skills []string
375	
376		for _, line := range lines {
377			if line.Type != transcript.TypeAssistant {
378				continue
379			}
380	
381			var msg transcript.AssistantMessage
382			if err := json.Unmarshal(line.Message, &msg); err != nil {
383				continue
384			}
385	
386			for _, block := range msg.Content {
387				if block.Type != transcript.ContentTypeToolUse || block.Name != "Skill" {
388					continue
389				}
390	
391				var input transcript.ToolInput
392				if err := json.Unmarshal(block.Input, &input); err != nil {
393					continue
394				}
395	
396				skill := strings.TrimSpace(input.Skill)
397				if skill == "" || seen[skill] {
398					continue
399				}
400	
401				seen[skill] = true
402				skills = append(skills, skill)
403			}
404		}
405	
406		return skills, nil
407	}
