32	func (m *pickerModel) setData(skills []skilldb.SkillRow, stats map[string]*skilldb.SkillStatsResult) {
33		// Deduplicate skills by name — the same skill may be discovered for
34		// multiple source agents (e.g. claude-code and gemini-cli).
35		// Keep one row per name and merge stats across agents.
36		seen := make(map[string]int) // name -> index in deduped
37		var deduped []skilldb.SkillRow
38		merged := make(map[string]*skilldb.SkillStatsResult)
39	
40		for _, skill := range skills {
41			key := skill.Name + "|" + skill.SourceAgent
42			st := stats[key]
43	
44			if idx, ok := seen[skill.Name]; ok {
45				// Merge stats into existing entry.
46				if existing := merged[deduped[idx].Name]; existing != nil && st != nil {
47					existing.TotalSessions += st.TotalSessions
48					existing.TotalFriction += st.TotalFriction
49					existing.TotalTokens += st.TotalTokens
50					if !st.FirstUsed.IsZero() && (existing.FirstUsed.IsZero() || st.FirstUsed.Before(existing.FirstUsed)) {
51						existing.FirstUsed = st.FirstUsed
52					}
53					if st.LastUsed.After(existing.LastUsed) {
54						existing.LastUsed = st.LastUsed
55					}
56					if existing.TotalSessions > 0 {
57						existing.SessionsPerWeek += st.SessionsPerWeek
58						existing.AvgScore = (existing.AvgScore*float64(existing.TotalSessions-st.TotalSessions) +
59							st.AvgScore*float64(st.TotalSessions)) / float64(existing.TotalSessions)
60					}
61				} else if existing == nil && st != nil {
62					merged[deduped[idx].Name] = st
63				}
64				continue
65			}
66	
67			seen[skill.Name] = len(deduped)
68			deduped = append(deduped, skill)
