70				cp := *st
71				merged[skill.Name] = &cp
72			}
73		}
74	
75		// Rekey stats by "name|sourceAgent" for the kept rows.
76		m.stats = make(map[string]*skilldb.SkillStatsResult, len(deduped))
77		for _, skill := range deduped {
78			key := skill.Name + "|" + skill.SourceAgent
79			m.stats[key] = merged[skill.Name]
