61	// Run launches the skill improvement TUI program.
62	func Run(ctx context.Context, skillDBPath, insightsDBPath, repoRoot string) error {
63		sdb, err := skilldb.Open(skillDBPath)
64		if err != nil {
65			return fmt.Errorf("open skill database: %w", err)
66		}
67		defer sdb.Close()
68	
69		idb, err := insightsdb.Open(insightsDBPath)
70		if err != nil {
71			return fmt.Errorf("open insights database: %w", err)
72		}
73		defer idb.Close()
74	
75		styles := newStyles()
76		m := rootModel{
77			ctx:        ctx,
78			styles:     styles,
79			width:      maxWidth,
80			skillDB:    sdb,
81			insightsDB: idb,
82			generator:  &skillimprove.Generator{},
83			repoRoot:   repoRoot,
84			picker:     newPickerModel(styles),
85			improveTab: newImproveModel(styles),
86		}
87	
88		p := tea.NewProgram(m, tea.WithAltScreen())
89		_, runErr := p.Run()
90		if runErr != nil {
91			return fmt.Errorf("run TUI: %w", runErr)
92		}
93		return nil
94	}
