191	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
192	func (m rootModel) handleDashboardKeys(msg tea.KeyMsg) (tea.Model, tea.Cmd) {
193		switch {
194		case key.Matches(msg, globalKeyMap.Quit):
195			return m, tea.Quit
196		case key.Matches(msg, globalKeyMap.Help):
197			m.showHelp = !m.showHelp
198			return m, nil
199		case key.Matches(msg, globalKeyMap.TabNext):
200			m.activeTab = (m.activeTab + 1) % 3
201			return m, nil
202		case key.Matches(msg, globalKeyMap.TabPrev):
203			m.activeTab = (m.activeTab + 2) % 3
204			return m, nil
205		case key.Matches(msg, globalKeyMap.Tab1):
206			m.activeTab = tabStats
207			return m, nil
208		case key.Matches(msg, globalKeyMap.Tab2):
209			m.activeTab = tabFriction
210			return m, nil
211		case key.Matches(msg, globalKeyMap.Tab3):
212			m.activeTab = tabImprove
213			return m, nil
214		case key.Matches(msg, dashboardKeyMap.Back):
215			return m, func() tea.Msg { return backToPickerMsg{} }
216		case key.Matches(msg, dashboardKeyMap.Refresh):
217			return m, func() tea.Msg { return refreshMsg{} }
218		default:
219			return m.delegateToActiveTab(msg)
220		}
221	}
