223	//nolint:ireturn // returns tea.Model as required by bubbletea dispatch pattern
224	func (m rootModel) handleSpinnerTick(msg spinner.TickMsg) (tea.Model, tea.Cmd) {
225		if m.improveTab.isGenerating {
226			var cmd tea.Cmd
227			m.improveTab.spinner, cmd = m.improveTab.spinner.Update(msg)
228			return m, cmd
229		}
230		return m, nil
