314	func (m *rootModel) removeSuggestion(index int) {
315		if index < len(m.improveTab.suggestions) {
316			m.improveTab.suggestions = append(
317				m.improveTab.suggestions[:index],
318				m.improveTab.suggestions[index+1:]...,
319			)
320			if m.improveTab.selected >= len(m.improveTab.suggestions) && m.improveTab.selected > 0 {
321				m.improveTab.selected--
322			}
323		}
324	}
