407	func (m rootModel) loadSkillDetail(skill skilldb.SkillRow) tea.Cmd {
408		return func() tea.Msg {
409			stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
410			if err != nil {
411				return skillDetailLoadedMsg{err: fmt.Errorf("load skill stats: %w", err)}
412			}
413	
414			sessions, err := m.skillDB.RecentSessions(m.ctx, skill.Name, skill.SourceAgent, 10)
415			if err != nil {
416				return skillDetailLoadedMsg{err: fmt.Errorf("load recent sessions: %w", err)}
417			}
418	
419			friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
420			if err != nil {
421				return skillDetailLoadedMsg{err: fmt.Errorf("load friction themes: %w", err)}
422			}
423	
424			missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
425			if err != nil {
426				return skillDetailLoadedMsg{err: fmt.Errorf("load missing instructions: %w", err)}
427			}
428	
429			agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
430			if err != nil {
431				return skillDetailLoadedMsg{err: fmt.Errorf("load agent breakdown: %w", err)}
432			}
433	
434			improvements, err := m.skillDB.ListImprovements(m.ctx, skill.Name, skill.SourceAgent, "")
435			if err != nil {
436				return skillDetailLoadedMsg{err: fmt.Errorf("load improvements: %w", err)}
437			}
438	
439			return skillDetailLoadedMsg{
440				stats:        stats,
441				sessions:     sessions,
442				friction:     friction,
443				missing:      missing,
444				agents:       agents,
445				improvements: improvements,
446			}
447		}
448	}
