450	func (m rootModel) generateSuggestions() tea.Cmd {
451		return func() tea.Msg {
452			if m.selectedSkill == nil {
453				return generateDoneMsg{err: errors.New("no skill selected")}
454			}
455	
456			skill := *m.selectedSkill
457	
458			// Read skill file content.
459			skillPath := filepath.Join(m.repoRoot, skill.Path)
460			content, err := os.ReadFile(skillPath) //nolint:gosec // path is constructed from repo root + db path
461			if err != nil {
462				return generateDoneMsg{err: fmt.Errorf("read skill file: %w", err)}
463			}
464	
465			// Load data needed for the request.
466			stats, err := m.skillDB.SkillStats(m.ctx, skill.Name, skill.SourceAgent)
467			if err != nil {
468				return generateDoneMsg{err: fmt.Errorf("load stats: %w", err)}
469			}
470	
471			friction, err := m.skillDB.SkillFrictionThemes(m.ctx, skill.Name, skill.SourceAgent)
472			if err != nil {
473				return generateDoneMsg{err: fmt.Errorf("load friction: %w", err)}
474			}
475	
476			missing, err := m.skillDB.SkillMissingInstructions(m.ctx, skill.Name, skill.SourceAgent)
477			if err != nil {
478				return generateDoneMsg{err: fmt.Errorf("load missing: %w", err)}
479			}
480	
481			agents, err := m.skillDB.AgentBreakdown(m.ctx, skill.Name, skill.SourceAgent)
482			if err != nil {
483				return generateDoneMsg{err: fmt.Errorf("load agents: %w", err)}
484			}
485	
486			// Build the request.
487			frictionRate := 0.0
488			if stats.TotalSessions > 0 {
489				frictionRate = float64(stats.TotalFriction) / float64(stats.TotalSessions) * 100
490			}
491	
492			var frictionThemes []skillimprove.FrictionTheme
493			for _, f := range friction {
