11	// Scope constants for skill discovery.
12	const (
13		ScopeRepo     = "repo"
14		ScopePersonal = "personal"
15	)
16	
17	// DiscoveredSkill represents a skill file found in an agent's config directory.
18	type DiscoveredSkill struct {
19		Name        string // skill name (e.g., "e2e", "dev")
20		SourceAgent string // "claude-code" or "gemini-cli"
21		Path        string // relative path from base dir (repo root or home)
22		Kind        string // "skill", "command", or "agent-def"
23		Scope       string // "repo" or "personal"
24	}
25	
26	// DiscoverSkills scans both the repo root and user home for skill files.
27	// Missing directories are silently skipped.
28	func DiscoverSkills(repoRoot string) ([]DiscoveredSkill, error) {
29		homeDir, err := os.UserHomeDir()
30		if err != nil {
31			homeDir = "" // skip personal skills if home dir unavailable
32		}
33	
34		var skills []DiscoveredSkill
35	
36		// Repo skills
37		repoSkills, err := discoverSkillsIn(repoRoot, repoRoot, ScopeRepo)
38		if err != nil {
39			return nil, fmt.Errorf("repo skills: %w", err)
40		}
41		skills = append(skills, repoSkills...)
42	
43		// Personal skills (from ~/.claude/, ~/.gemini/)
44		if homeDir != "" {
45			personalSkills, pErr := discoverSkillsIn(homeDir, homeDir, ScopePersonal)
46			if pErr != nil {
47				return nil, fmt.Errorf("personal skills: %w", pErr)
48			}
49			// Deduplicate: skip personal skills that have the same name+agent as a repo skill.
50			repoNames := make(map[string]bool, len(repoSkills))
51			for _, s := range repoSkills {
52				repoNames[s.Name+"|"+s.SourceAgent] = true
53			}
54			for _, s := range personalSkills {
55				if !repoNames[s.Name+"|"+s.SourceAgent] {
56					skills = append(skills, s)
57				}
58			}
59		}
60	
61		sort.Slice(skills, func(i, j int) bool {
62			// Repo skills first, then personal.
63			if skills[i].Scope != skills[j].Scope {
64				return skills[i].Scope < skills[j].Scope // "personal" < "repo" alphabetically, so reverse
65			}
66			if skills[i].SourceAgent != skills[j].SourceAgent {
67				return skills[i].SourceAgent < skills[j].SourceAgent
68			}
69			return skills[i].Name < skills[j].Name
70		})
71	
72		return skills, nil
73	}
74	
75	func discoverSkillsIn(baseDir, relBase, scope string) ([]DiscoveredSkill, error) {
76		var skills []DiscoveredSkill
77	
78		collectors := []struct {
79			pattern     string
80			sourceAgent string
81			kind        string
82			nameFunc    func(match string) string
83			readContent bool
84		}{
85			{
86				pattern:     filepath.Join(baseDir, ".claude", "skills", "*", "SKILL.md"),
87				sourceAgent: "claude-code",
88				kind:        "skill",
89				nameFunc:    func(match string) string { return filepath.Base(filepath.Dir(match)) },
90			},
91			{
92				pattern:     filepath.Join(baseDir, ".claude", "commands", "*.md"),
93				sourceAgent: "claude-code",
94				kind:        "command",
95				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
96			},
97			{
98				pattern:     filepath.Join(baseDir, ".gemini", "agents", "*.md"),
99				sourceAgent: "gemini-cli",
100				kind:        "agent-def",
101				readContent: true,
102				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
103			},
104			{
105				pattern:     filepath.Join(baseDir, ".gemini", "commands", "*.md"),
106				sourceAgent: "gemini-cli",
107				kind:        "command",
108				readContent: true,
109				nameFunc:    func(match string) string { return strings.TrimSuffix(filepath.Base(match), ".md") },
110			},
111		}
112	
113		for _, c := range collectors {
114			matches, err := filepath.Glob(c.pattern)
115			if err != nil {
116				return nil, fmt.Errorf("globbing %s: %w", c.pattern, err)
117			}
118	
119			for _, match := range matches {
120				name := c.nameFunc(match)
121	
122				if c.readContent {
123					content, err := os.ReadFile(match) //nolint:gosec // match comes from filepath.Glob, not user input
124					if err != nil {
125						return nil, fmt.Errorf("reading %s: %w", match, err)
126					}
127					if yamlName := extractYAMLName(string(content)); yamlName != "" {
128						name = yamlName
129					}
130				}
131	
132				relPath, err := filepath.Rel(relBase, match)
133				if err != nil {
134					return nil, fmt.Errorf("computing relative path for %s: %w", match, err)
135				}
136	
137				skills = append(skills, DiscoveredSkill{
138					Name:        name,
139					SourceAgent: c.sourceAgent,
140					Path:        relPath,
141					Kind:        c.kind,
142					Scope:       scope,
143				})
144			}
145		}
146	
147		return skills, nil
148	}
149	
150	// extractYAMLName looks for a name field in YAML frontmatter delimited by "---".
151	func extractYAMLName(content string) string {
152		lines := strings.Split(content, "\n")
153		if len(lines) == 0 || strings.TrimSpace(lines[0]) != "---" {
154			return ""
155		}
156	
157		for _, line := range lines[1:] {
158			trimmed := strings.TrimSpace(line)
159			if trimmed == "---" {
160				break
161			}
162			if strings.HasPrefix(trimmed, "name:") {
163				value := strings.TrimPrefix(trimmed, "name:")
164				return strings.TrimSpace(value)
165			}
166		}
167	
168		return ""
169	}
