)

func main() {
	ctx := context.Background()
	repoRoot := "/Users/alisha/.superset/worktrees/cli/agent-improvements"

	idb, err := insightsdb.Open(repoRoot + "/.entire/insights.db")
	if err != nil { log.Fatal(err) }
	defer idb.Close()

	sdb, err := skilldb.Open(repoRoot + "/.entire/skill-analytics.db")
	if err != nil { log.Fatal(err) }
	defer sdb.Close()

	discovered, err := skilldb.DiscoverSkills(repoRoot)
	if err != nil { log.Fatal(err) }

	fmt.Printf("Discovered %d skills\n", len(discovered))
	for _, d := range discovered {
		fmt.Printf("  %s (%s) [%s] %s\n", d.Name, d.SourceAgent, d.Scope, d.Kind)
	}

	rows := make([]skilldb.SkillRow, len(discovered))
	now := time.Now().UTC()
	for i, d := range discovered {
		rows[i] = skilldb.SkillRow{
			Name: d.Name, SourceAgent: d.SourceAgent, Path: d.Path,
			Kind: d.Kind, Scope: d.Scope, DiscoveredAt: now, LastSeenAt: now,
		}
	}

	refreshed, err := sdb.RefreshFromInsightsDB(ctx, idb, rows, repoRoot)
	if err != nil { log.Fatal("refresh error:", err) }
	fmt.Printf("Refreshed: %v\n", refreshed)

	// Check friction
	for _, skill := range rows {
		themes, _ := sdb.SkillFrictionThemes(ctx, skill.Name, skill.SourceAgent)
		if len(themes) > 0 {
			fmt.Printf("FRICTION for %s: %d themes\n", skill.Name, len(themes))
			for _, t := range themes {
				fmt.Printf("  [%dx] %s\n", t.Count, t.Text[:min(80, len(t.Text))])
			}
		}
	}

	stats, _ := sdb.SkillStats(ctx, "brainstorming", "claude-code")
	fmt.Printf("\nbrainstorming stats: sessions=%d friction=%d\n", stats.TotalSessions, stats.TotalFriction)
}

